"$routes = @('', 'about', 'project', 'worship', 'events', 'community', 'gallery', 'governance', 'contact', 'membership', 'donate', 'volunteer', 'admin')
$base = 'https://bhtcc.netlify.app'
$allLinks = @{}

foreach ($r in $routes) {
    $url = "$base/$r"
    Write-Host "Fetching $url..."
    $html = (curl.exe -sL $url) -join "`n"
    $filename = if ($r -eq '') { "home.html" } else { "$r.html" }
    $html | Out-File -FilePath "C:\Users\amara\.gemini\antigravity\brain\bb026828-c495-42ca-b6b7-042920e4c9a9\scratch\$filename" -Encoding utf8

    $matches = [regex]::Matches($html, 'href="([^"]+)"')
    foreach ($m in $matches) {
        $href = $m.Groups[1].Value
        $allLinks[$href] = $true
    }
}

Write-Host "=== All Distinct Links Found Across Pages ==="
$allLinks.Keys | Sort-Object"

"$files = Get-ChildItem "C:\Users\amara\.gemini\antigravity\brain\bb026828-c495-42ca-b6b7-042920e4c9a9\scratch\*.html"
$chunks = @{}
$base = "https://bhtcc.netlify.app"

foreach ($f in $files) {
    $content = Get-Content $f.FullName -Raw
    $matches = [regex]::Matches($content, 'src="(/_next/static/chunks/[^"]+)"')
    foreach ($m in $matches) {
        $chunks[$m.Groups[1].Value] = $true
    }
}

Write-Host "Found $($chunks.Count) distinct chunks."
foreach ($chunk in $chunks.Keys) {
    $chunkUrl = "$base$chunk"
    $chunkFile = [System.IO.Path]::GetFileName($chunk)
    Write-Host "Downloading $chunkFile..."
    curl.exe -sL $chunkUrl -o "C:\Users\amara\.gemini\antigravity\brain\bb026828-c495-42ca-b6b7-042920e4c9a9\scratch\$chunkFile"
}"

"$files = Get-ChildItem "C:\Users\amara\.gemini\antigravity\brain\bb026828-c495-42ca-b6b7-042920e4c9a9\scratch\*.html"
foreach ($f in $files) {
    $content = Get-Content $f.FullName -Raw
    # Next.js page scripts are usually loaded near the bottom or in the head
    $scripts = [regex]::Matches($content, 'src="(/_next/static/chunks/[^"]+)"') | ForEach-Object { $_.Groups[1].Value }
    Write-Host "$($f.BaseName):"
    $scripts | ForEach-Object { Write-Host "   $_" }
}"

